-- Migration 010: allow 'hammerhead' (SRAM Hammerhead Karoo) as a provider
--
-- Why
--   Every provider/source column has a CHECK constraint listing the allowed
--   providers ('strava','coros','garmin','wahoo'). Hammerhead rows would be
--   rejected until it is added.
--
-- Columns covered
--   activities.source, athletes.source, athlete_providers.provider,
--   oauth_states.provider, athlete_monthly_totals.source
--
-- How
--   Some of these CHECKs were created inline, so their names were generated by
--   Postgres. Instead of guessing names, drop every CHECK on the column whose
--   definition contains 'strava' (i.e. the provider list), then add one
--   explicitly named CHECK with the new list.
--
-- Run in the Supabase SQL editor. Idempotent. Run it BEFORE the app deploy that
-- enables the Hammerhead button.

do $$
declare
    target record;
    con record;
    allowed text := '(''strava'', ''coros'', ''garmin'', ''wahoo'', ''hammerhead'')';
begin
    for target in
        select * from (values
            ('activities',             'source',   'activities_source_check'),
            ('athletes',               'source',   'athletes_source_check'),
            ('athlete_providers',      'provider', 'athlete_providers_provider_check'),
            ('oauth_states',           'provider', 'oauth_states_provider_check'),
            ('athlete_monthly_totals', 'source',   'athlete_monthly_totals_source_check')
        ) as t(tbl, col, conname)
    loop
        for con in
            select c.conname
            from pg_constraint c
            where c.conrelid = format('public.%I', target.tbl)::regclass
              and c.contype = 'c'
              and pg_get_constraintdef(c.oid) ilike '%' || target.col || '%'
              and pg_get_constraintdef(c.oid) ilike '%strava%'
        loop
            execute format('alter table public.%I drop constraint %I', target.tbl, con.conname);
        end loop;

        execute format(
            'alter table public.%I add constraint %I check (%I in %s)',
            target.tbl, target.conname, target.col, allowed
        );
    end loop;
end $$;

-- Verify (expected: 5 rows, each listing hammerhead):
--   select conrelid::regclass as tbl, conname, pg_get_constraintdef(oid)
--   from pg_constraint
--   where contype = 'c' and pg_get_constraintdef(oid) ilike '%hammerhead%';
